 23	async function jsonRequest(fetchImpl, url, init = {}, expectJson = true) {
 24	  try {
 25	    const response = await fetchImpl(url, init);
 26	    if (!expectJson) return { response };
 27	    const contentType = response.headers.get('content-type') ?? '';
 28	    let body;
 29	    try {
 30	      body = await response.json();
 31	    } catch {
 32	      return { response, reason: 'invalid_json' };
 33	    }
 34	    return { response, body, contentType };
 35	  } catch {
 36	    return { reason: 'backend_unreachable' };
 37	  }
 38	}
