 40	function nonEmpty(value) {
 41	  if (Array.isArray(value)) return value.length > 0;
 42	  return (
 43	    value &&
 44	    typeof value === 'object' &&
 45	    Object.keys(value).length > 0 &&
 46	    (!Array.isArray(value.items) || value.items.length > 0)
 47	  );
 48	}
 49	
 50	function itemsOf(value) {
 51	  if (Array.isArray(value)) return value;
 52	  if (Array.isArray(value?.items)) return value.items;
 53	  if (Array.isArray(value?.data)) return value.data;
 54	  return [];
 55	}
 56	
 57	function containsFixtureId(value, expectedId) {
 58	  if (!expectedId) return true;
 59	  return itemsOf(value).some((item) => {
 60	    if (!item || typeof item !== 'object') return false;
 61	    return Object.values(item).some((field) => field === expectedId);
 62	  });
 63	}
 64	
 65	function matchesLayer(value, expectedLayer) {
 66	  if (!expectedLayer) return true;
 67	  const items = itemsOf(value);
 68	  return (
 69	    items.length > 0 &&
 70	    items.every(
 71	      (item) =>
 72	        item?.object?.layer === expectedLayer && item.object.ref === null,
 73	    )
 74	  );
 75	}
