 77	async function writeReport(report, suffix = '') {
 78	  await mkdir(evidenceDir, { recursive: true });
 79	  const safe = { ...report, rows: report.rows.map(evidenceRow) };
 80	  const stem = suffix ? `smoke-report-${suffix}` : 'smoke-report';
 81	  await writeFile(
 82	    join(evidenceDir, `${stem}.json`),
 83	    `${JSON.stringify(safe, null, 2)}\n`,
 84	  );
 85	  await writeFile(
 86	    join(evidenceDir, `${stem}.txt`),
 87	    safe.rows
 88	      .map(
 89	        (row) => `${row.target}\t${row.result}\t${row.reason}\t${row.status}`,
 90	      )
 91	      .join('\n') + '\n',
 92	  );
 93	}
