 95	export async function runSmoke({ targets, fetchImpl = fetch, evidenceSuffix }) {
 96	  const rows = [];
 97	  const add = (row) => rows.push(row);
 98	  const check = async (
 99	    target,
100	    url,
101	    expected = 200,
102	    init,
103	    expectJson = true,
104	  ) => {
105	    const result = await jsonRequest(fetchImpl, url, init, expectJson);
106	    if (!result.response)
107	      return add({
108	        target,
109	        result: 'failed',
110	        reason: result.reason,
111	        status: 0,
112	        url,
113	      });
114	    if (result.response.status !== expected)
115	      return add({
116	        target,
117	        result: 'failed',
118	        reason:
119	          result.response.status === 401
120	            ? 'unauthorized'
121	            : result.response.status === 403
122	              ? 'forbidden'
123	              : `unexpected_status_${result.response.status}`,
124	        status: result.response.status,
125	        url,
126	      });
127	    if (result.reason)
128	      return add({
129	        target,
130	        result: 'failed',
131	        reason: result.reason,
132	        status: result.response.status,
133	        url,
134	      });
135	    return add({
136	      target,
137	      result: 'passed',
138	      reason: 'ok',
139	      status: result.response.status,
140	      url,
141	      body: result.body,
142	    });
143	  };
144	
145	  for (const path of targets.backend.health)
146	    await check(`backend.${path.slice(1)}`, `${targets.backend.url}${path}`);
147	  for (const service of [targets.senatran, targets.sefaz])
148	    for (const path of service.health)
149	      await check(
150	        service === targets.sefaz ? 'sefaz.health' : 'senatran.health',
151	        `${service.url}${path}`,
152	      );
153	  for (const frontend of targets.frontends) {
154	    await check(
155	      `frontend.${frontend.name}.root`,
156	      `${frontend.rootUrl}/`,
157	      200,
158	      undefined,
159	      false,
160	    );
161	    const result = await jsonRequest(
162	      fetchImpl,
163	      `${frontend.proxyUrl}${frontend.readPath}`,
164	      { headers: authHeaders },
165	    );
166	    const row = {
167	      target: `frontend.${frontend.name}.proxy`,
168	      persona: frontend.persona,
169	      fixture: frontend.fixture,
170	      route: frontend.readPath,
171	      policy: frontend.policy,
172	      expectedId: frontend.expectedId,
173	      url: `${frontend.proxyUrl}${frontend.readPath}`,
174	    };
175	    if (!result.response)
176	      add({
177	        ...row,
178	        result: 'failed',
179	        reason: 'backend_unreachable',
180	        status: 0,
181	      });
182	    else if (result.response.status !== 200)
183	      add({
184	        ...row,
185	        result: 'failed',
186	        reason:
187	          result.response.status === 401
188	            ? 'unauthorized'
189	            : result.response.status === 403
190	              ? 'forbidden'
191	              : `unexpected_status_${result.response.status}`,
192	        status: result.response.status,
193	      });
194	    else if (result.reason)
195	      add({ ...row, result: 'failed', reason: result.reason, status: 200 });
196	    else if (!nonEmpty(result.body))
197	      add({ ...row, result: 'failed', reason: 'empty_json', status: 200 });
198	    else if (
199	      frontend.expectedTenant &&
200	      result.body.tenantId &&
201	      result.body.tenantId !== frontend.expectedTenant
202	    )
203	      add({ ...row, result: 'failed', reason: 'tenant_mismatch', status: 200 });
204	    else if (!containsFixtureId(result.body, frontend.expectedId))
205	      add({
206	        ...row,
207	        result: 'failed',
208	        reason: 'fixture_id_missing',
209	        status: 200,
210	      });
211	    else if (!matchesLayer(result.body, frontend.expectedLayer))
212	      add({ ...row, result: 'failed', reason: 'layer_mismatch', status: 200 });
213	    else add({ ...row, result: 'passed', reason: 'ok', status: 200 });
214	  }
215	  const pec = { state: targets.pec?.state ?? 'not_built_r0031' };
216	  for (const probe of targets.ch ?? []) {
217	    const result = await jsonRequest(
218	      fetchImpl,
219	      `${probe.proxyUrl ?? targets.frontends[0].proxyUrl}${probe.path}`,
220	      {
221	        method: 'POST',
222	        headers: {
223	          ...authHeaders,
224	          'content-type': 'application/json',
225	          'idempotency-key': randomUUID(),
226	        },
227	        body: JSON.stringify(probe.body ?? {}),
228	      },
229	    );
230	    const row = {
231	      target: `ch.${probe.name}`,
232	      persona: probe.persona,
233	      fixture: probe.fixture,
234	      route: probe.path,
235	      policy: probe.policy,
236	      precondition: probe.precondition,
237	      url: `${probe.proxyUrl ?? targets.frontends[0].proxyUrl}${probe.path}`,
238	    };
239	    if (!result.response)
240	      add({
241	        ...row,
242	        result: 'blocked_before_adapter',
243	        reason: 'backend_unreachable',
244	        status: 0,
245	      });
246	    else if (result.response.status !== 503)
247	      add({
248	        ...row,
249	        result: 'blocked_before_adapter',
250	        reason: `unexpected_status_${result.response.status}`,
251	        status: result.response.status,
252	      });
253	    else if (result.reason)
254	      add({
255	        ...row,
256	        result: 'blocked_before_adapter',
257	        reason: result.reason,
258	        status: 503,
259	      });
260	    else if (probe.message && result.body?.message !== probe.message)
261	      add({
262	        ...row,
263	        result: 'blocked_before_adapter',
264	        reason: 'adapter_message_mismatch',
265	        status: 503,
266	        adapterMessage: result.body?.message,
267	      });
268	    else
269	      add({
270	        ...row,
271	        result: 'passed',
272	        reason: 'adapter_unconfigured',
273	        status: 503,
274	        adapterMessage: result.body?.message,
275	      });
276	  }
277	  const complete = rows.every((row) => row.result === 'passed');
278	  const report = {
279	    complete,
280	    pec,
281	    rows: rows.map(({ body: _body, ...row }) => row),
282	  };
283	  await writeReport(report, evidenceSuffix);
284	  return report;
285	}
