431	async function runCli() {
432	  const rows = [];
433	  const preflight = await backendPreflight();
434	  if (!preflight) {
435	    const report = {
436	      complete: false,
437	      pec: { state: defaultTargets.pec.state },
438	      rows: [
439	        {
440	          target: 'backend.healthz',
441	          result: 'failed',
442	          reason: 'backend_unreachable',
443	          status: 0,
444	        },
445	      ],
446	    };
447	    await writeReport(report);
448	    return report;
449	  }
450	
451	  let restartAttempted = false;
452	  const restore = async () => {
453	    if (!restartAttempted) return true;
454	    return restartFor(defaultRoles);
455	  };
456	  const onSignal = () => {
457	    void restore().finally(() => process.exit(1));
458	  };
459	  process.once('SIGINT', onSignal);
460	  process.once('SIGTERM', onSignal);
461	  try {
462	    const portalGuard = command(
463	      'bash',
464	      ['tools/detran-stack.sh', 'fixture-portal'],
465	      {
466	        DB_NAME: 'not_detran_local_stack',
467	      },
468	    );
469	    rows.push({
470	      target: 'fixture.portal.database_guard',
471	      result:
472	        portalGuard.status !== 0 &&
473	        portalGuard.stderr.includes(
474	          'stack database is restricted to DB_NAME=detran_local_stack',
475	        )
476	          ? 'passed'
477	          : 'failed',
478	      reason: 'db_name_rejected',
479	      status: portalGuard.status ?? 1,
480	      command:
481	        'DB_NAME=not_detran_local_stack tools/detran-stack.sh fixture-portal',
482	      message: portalGuard.stderr.trim(),
483	    });
484	    const portalFixture = command('bash', [
485	      'tools/detran-stack.sh',
486	      'fixture-portal',
487	    ]);
488	    rows.push({
489	      target: 'fixture.portal',
490	      result: portalFixture.status === 0 ? 'passed' : 'failed',
491	      reason: portalFixture.status === 0 ? 'applied' : 'fixture_apply_failed',
492	      status: portalFixture.status ?? 1,
493	    });
494	    for (const frontend of defaultTargets.frontends) {
495	      restartAttempted = true;
496	      if (!(await restartFor(frontend.persona))) {
497	        rows.push({
498	          target: `persona.${frontend.persona}`,
499	          result: 'failed',
500	          reason: 'backend_restart_failed',
501	          status: 0,
502	        });
503	        continue;
504	      }
505	      const report = await runSmoke({
506	        targets: phaseTargets([frontend]),
507	        evidenceSuffix: frontend.name,
508	      });
509	      rows.push(...report.rows);
510	    }
511	
512	    const guard = command('bash', ['tools/detran-stack.sh', 'fixture-ch'], {
513	      DB_NAME: 'not_detran_local_stack',
514	    });
515	    rows.push({
516	      target: 'fixture.database_guard',
517	      result:
518	        guard.status !== 0 &&
519	        guard.stderr.includes(
520	          'stack database is restricted to DB_NAME=detran_local_stack',
521	        )
522	          ? 'passed'
523	          : 'failed',
524	      reason: 'db_name_rejected',
525	      status: guard.status ?? 1,
526	      command:
527	        'DB_NAME=not_detran_local_stack tools/detran-stack.sh fixture-ch',
528	      message: guard.stderr.trim(),
529	    });
530	    const fixture = command('bash', ['tools/detran-stack.sh', 'fixture-ch']);
531	    if (fixture.status !== 0) {
532	      rows.push({
533	        target: 'fixture.ch',
534	        result: 'failed',
535	        reason: 'fixture_apply_failed',
536	        status: fixture.status ?? 1,
537	      });
538	    } else {
539	      for (const probe of defaultTargets.ch) {
540	        restartAttempted = true;
541	        if (!(await restartFor(probe.persona, probe.actorId))) {
542	          rows.push({
543	            target: `persona.${probe.persona}`,
544	            result: 'failed',
545	            reason: 'backend_restart_failed',
546	            status: 0,
547	          });
548	          continue;
549	        }
550	        const report = await runSmoke({
551	          targets: phaseTargets([], [probe]),
552	          evidenceSuffix: `ch-${probe.name}`,
553	        });
554	        rows.push(...report.rows);
555	      }
556	    }
557	  } finally {
558	    if (!(await restore())) {
559	      rows.push({
560	        target: 'persona.restore_defaults',
561	        result: 'failed',
562	        reason: 'backend_restart_failed',
563	        status: 0,
564	      });
565	    }
566	    process.removeListener('SIGINT', onSignal);
567	    process.removeListener('SIGTERM', onSignal);
568	  }
569	  const report = {
570	    complete: rows.every((row) => row.result === 'passed'),
571	    pec: { state: defaultTargets.pec.state },
572	    rows,
573	  };
574	  await writeReport(report);
575	  return report;
576	}
