 17	function failure(
 18	  response,
 19	  status,
 20	  category,
 21	  code,
 22	  message,
 23	  requestId,
 24	  headers,
 25	) {
 26	  send(
 27	    response,
 28	    status,
 29	    {
 30	      requestId,
 31	      error: {
 32	        category,
 33	        code,
 34	        message,
 35	        retryable: false,
 36	        providerStatus: status,
 37	      },
 38	    },
 39	    headers,
 40	  );
 41	}
