 43	async function readJson(request) {
 44	  let text = '';
 45	  for await (const chunk of request) text += chunk;
 46	  if (!text) return {};
 47	  try {
 48	    const value = JSON.parse(text);
 49	    return value && typeof value === 'object' && !Array.isArray(value)
 50	      ? value
 51	      : null;
 52	  } catch {
 53	    return null;
 54	  }
 55	}
