 57	export async function createSefazMockServer({ host, port }) {
 58	  const server = createServer(async (request, response) => {
 59	    const url = new URL(
 60	      request.url ?? '/',
 61	      `http://${request.headers.host ?? host}`,
 62	    );
 63	    if (request.method === 'GET' && url.pathname === '/health') {
 64	      return send(response, 200, { status: 'ok', service: 'sefaz-mock' });
 65	    }
 66	    const requestId = testRequestId(`${request.method}-${url.pathname}`);
 67	    const postRoutes = new Set([
 68	      '/mock/sefaz/payments/lookup',
 69	      '/mock/sefaz/guides',
 70	      '/mock/sefaz/rectifications',
 71	      '/mock/sefaz/refunds',
 72	    ]);
 73	    if (postRoutes.has(url.pathname) && request.method !== 'POST') {
 74	      return failure(
 75	        response,
 76	        405,
 77	        'BUSINESS_ERROR',
 78	        'method_not_allowed',
 79	        'Method not allowed',
 80	        requestId,
 81	        { allow: 'POST' },
 82	      );
 83	    }
 84	    if (
 85	      !postRoutes.has(url.pathname) &&
 86	      (url.pathname.startsWith('/mock/sefaz/payments/') ||
 87	        url.pathname.startsWith('/mock/sefaz/refunds/')) &&
 88	      request.method !== 'GET'
 89	    ) {
 90	      return failure(
 91	        response,
 92	        405,
 93	        'BUSINESS_ERROR',
 94	        'method_not_allowed',
 95	        'Method not allowed',
 96	        requestId,
 97	        { allow: 'GET' },
 98	      );
 99	    }
