 23	export class SefazHttpAdapter implements SefazPaymentPort {
 24	  private readonly baseUrl: string;
 25	  private readonly pathPrefix: string;
 26	  private readonly timeoutMs: number;
 27	  private readonly retryDelayMs: number;
 28	
 29	  constructor(options: SefazHttpAdapterOptions) {
 30	    if (!/^https?:\/\//u.test(options.baseUrl)) {
 31	      throw new Error('SEFAZ base URL must use http or https');
 32	    }
 33	    this.baseUrl = options.baseUrl.replace(/\/+$/u, '');
 34	    const prefix = (options.pathPrefix ?? '').trim().replace(/^\/+|\/+$/gu, '');
 35	    this.pathPrefix = prefix ? `/${prefix}` : '';
 36	    this.timeoutMs = options.timeoutMs ?? 10_000;
 37	    this.retryDelayMs = options.retryDelayMs ?? 120;
 38	  }
 39	
 40	  lookupDebt(input: DebtLookupInput): Promise<DebtLookupOutput> {
 41	    return this.request('POST', '/sefaz/payments/lookup', input);
 42	  }
 43	  issueGuide(input: IssueGuideInput): Promise<IssueGuideOutput> {
 44	    return this.request('POST', '/sefaz/guides', input);
 45	  }
 46	  getPaymentStatus(reference: string): Promise<PaymentStatusOutput> {
 47	    return this.request(
 48	      'GET',
 49	      `/sefaz/payments/${encodeURIComponent(reference)}`,
 50	    );
 51	  }
 52	  submitRectification(input: RectificationInput): Promise<RectificationOutput> {
 53	    return this.request('POST', '/sefaz/rectifications', input);
 54	  }
 55	  submitRefundRequest(input: RefundInput): Promise<RefundOutput> {
 56	    return this.request('POST', '/sefaz/refunds', input);
 57	  }
 58	  getRefundStatus(refundId: string): Promise<RefundStatusOutput> {
 59	    return this.request(
 60	      'GET',
 61	      `/sefaz/refunds/${encodeURIComponent(refundId)}`,
 62	    );
 63	  }
 64	
 65	  private async request<T>(
 66	    method: 'GET' | 'POST',
 67	    path: string,
 68	    body?: unknown,
 69	  ): Promise<T> {
 70	    let lastError: unknown;
 71	    for (let attempt = 0; attempt < 3; attempt += 1) {
 72	      try {
 73	        return await this.fetchOnce<T>(method, path, body);
 74	      } catch (error) {
 75	        lastError = error;
 76	        if (
 77	          !(error instanceof SefazAdapterError) ||
 78	          !error.retryable ||
 79	          attempt === 2
 80	        ) {
 81	          throw error;
 82	        }
 83	        if (this.retryDelayMs > 0) {
 84	          await new Promise((resolve) =>
 85	            setTimeout(resolve, this.retryDelayMs * 2 ** attempt),
 86	          );
 87	        }
 88	      }
 89	    }
 90	    throw lastError;
 91	  }
 92	
 93	  private async fetchOnce<T>(
 94	    method: 'GET' | 'POST',
 95	    path: string,
 96	    body?: unknown,
 97	  ): Promise<T> {
 98	    const controller = new AbortController();
 99	    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
100	    try {
101	      const response = await fetch(`${this.baseUrl}${this.pathPrefix}${path}`, {
102	        method,
103	        headers: {
104	          accept: 'application/json',
105	          ...(body === undefined ? {} : { 'content-type': 'application/json' }),
106	        },
107	        ...(body === undefined ? {} : { body: JSON.stringify(body) }),
108	        signal: controller.signal,
109	      });
110	      const payload = (await response.json()) as unknown;
111	      if (!response.ok) throw this.providerError(payload, response.status);
112	      return payload as T;
113	    } catch (error) {
114	      if (error instanceof SefazAdapterError) throw error;
115	      if ((error as { name?: string }).name === 'AbortError') {
116	        throw new SefazAdapterError(
117	          'SEFAZ request timed out',
118	          'TIMEOUT',
119	          'timeout',
120	          true,
121	        );
122	      }
123	      throw new SefazAdapterError(
124	        error instanceof Error ? error.message : 'SEFAZ transport failure',
125	        'TRANSPORT_ERROR',
126	        'transport_error',
127	        true,
128	      );
129	    } finally {
130	      clearTimeout(timer);
131	    }
132	  }
133	
134	  private providerError(payload: unknown, status: number): SefazAdapterError {
135	    const envelope = payload as {
136	      error?: {
137	        category?: string;
138	        code?: string;
139	        message?: string;
140	        retryable?: boolean;
141	        providerStatus?: number;
142	      };
143	      requestId?: string;
144	    };
145	    const detail = envelope?.error;
146	    return new SefazAdapterError(
147	      detail?.message ?? `SEFAZ provider returned HTTP ${status}`,
148	      (detail?.category ?? 'PROVIDER_ERROR') as SefazErrorCategory,
149	      detail?.code ?? `http_${status}`,
150	      detail?.retryable ?? status >= 500,
151	      detail?.providerStatus ?? status,
152	      envelope?.requestId,
153	    );
154	  }
155	}
